insert into public.wf_cases(id,proc_id,applicant_name,applicant_ref,birth,form_name,blind,avg,status,reasons,findings,created_at,updated_at) values('s3_dc','s3','홍길동(합성)','citizen-0001','1980-01-01','사망 신고서','',100,'접수','["[승인] 기관 간 사망 정보 반영 시차", "[승인] 건강보험 자격 변동 신고기한 경과"]'::jsonb,'[{"stage": "원본대조", "code": "INTER_AGENCY_LAG", "role": "승인", "role_label": "승인 담당 · 종합 검토", "severity": "high", "title": "기관 간 사망 정보 반영 시차", "detail": "사망진단서 사망일 2026-10-28 ↔ 연계 사망정보 반영일 (합성 · 기관 간 시차) 2026-11-03 (6일 차이). 2026-10-28 ~ 2026-11-03 사이 고인 명의로 지급된 급여가 있는지 확인해야 합니다(사후 수급 의심 구간).", "evidence": [{"doc": "사망진단서_합성.pdf", "field": "사망일", "excerpt": "사망일: 2026-10-28"}], "gov": {"source": "연계 사망정보 반영일 (합성 · 기관 간 시차)", "field": "사망일", "value": "2026-11-03"}, "clause": null, "action": "고인 명의 급여 지급 내역 조회 · 환수 검토", "clause_links": [{"text": "국민연금법 제57조(급여의 환수)", "url": "https://www.law.go.kr/법령/국민연금법/제57조"}], "id": "DC-s3-001", "stage_seq": 2}, {"stage": "정책검증", "code": "DEADLINE_PASSED", "role": "승인", "role_label": "승인 담당 · 종합 검토", "severity": "medium", "title": "건강보험 자격 변동 신고기한 경과", "detail": "변동일 2026-10-28 + 14일 = 2026-11-11 < 신고일 2026-11-18 (7일 경과). 그 사이 보험료 부과·피부양자 자격이 소급 정리되는지 확인이 필요합니다.", "evidence": [{"doc": "건강보험자격변동신고서_합성.pdf", "field": "변동일", "excerpt": "변동일: 2026-10-28"}], "gov": null, "clause": "국민건강보험법 제9조제2항·제10조제2항 — 자격 변동·상실일부터 14일 이내 신고", "action": "소급 처리 확인", "clause_links": [{"text": "국민건강보험법 제9조(자격의 변동 시기 등)", "url": "https://www.law.go.kr/법령/국민건강보험법/제9조"}, {"text": "국민건강보험법 제10조(자격의 상실 시기 등)", "url": "https://www.law.go.kr/법령/국민건강보험법/제10조"}], "id": "DC-s3-002", "stage_seq": 2}, {"stage": "추출", "code": "MANUAL_PENDING", "role": "접수", "role_label": "접수 담당 · 입력 오류", "severity": "low", "title": "현장 작성 서류 미첨부: 사망 신고서", "detail": "현장방문으로 작성하는 서류입니다. 담당자가 작성본을 첨부해야 승인할 수 있습니다.", "evidence": [], "gov": null, "clause": null, "action": "작성본 첨부", "id": "DC-s3-003", "stage_seq": 0}, {"stage": "추출", "code": "MANUAL_PENDING", "role": "접수", "role_