-- 002 AI Double Check 연동 (welfare_ai/src/export_sakak.py 로 생성)
-- 1) 신청 건마다 판독 엔진의 점검 결과(오류·담당·근거·원본값)를 담는 칸
alter table public.wf_cases add column if not exists findings jsonb not null default '[]';
comment on column public.wf_cases.findings is 'AI Double Check 점검 결과 (welfare_ai). role=접수|심사|승인, stage_seq=결재자 0/1/2';

-- 2) 엔진이 실제 서류를 점검한 시연 신청 (시나리오 예시 서류, 합성 데이터)
delete from public.wf_cases where id = 's1_dc';

delete from public.wf_cases where id = 's2_dc';

delete from public.wf_cases where id = 's3_dc';

